import React, { useRef, useState } from 'react';
 import './UserStatus.css';





 function UserStatus({setPostsList,postsList},User) {
    console.log('render')
    const [search, setSearch] = useState('')
     const addPost = (text) => {
         const post = {
             "id": 11,
             "userPic": "birthday.jpg",
             "name":"new",
             text,
             "photo": "img10",
             "likes": "",
             "comments": ""
         }
         setPostsList([post,...postsList])
     }
   const searchBox = useRef(null)
//    const search =function(searchBox){
//      console.log(searchBox.current.valu)
//    }

     return (
        <div className = "status">
         <div class="card">
            
                 <div class="row">
                     <div class = "enterStatuse">
                    
                     <img src={User._picter} className="card-img-bottom" alt="userPec"></img>
                   
                     <div class = "statusetext">
                         <input ref={searchBox} value={search} onChange={e => setSearch(e.currentTarget.value)} class="search"  placeholder="What's on your mind?"
                             aria-label="Search"></input>
                     </div> 
                 </div>
                 </div>
                 <div class = "statusButton">
                 <button type="button" class="btn btn-light" onClick={() => addPost(search)}>Post</button>
                     <button type="button" class="btn btn-light">Live video</button>
                     <button type="button" class="btn btn-light">Photo/video</button>
                     <button type="button" class="btn btn-light">Feeling/activity</button>
                 </div>
             </div>
            
             </div>
             );
 }
             export default UserStatus;
